      'help.creditRewards': function (p) { return 'Hint credits for high scores (players logged in with a name): ' + p.list + '.'; },
      'help.modesCode': function (p) { return 'Expert level ⭐ (⚙ › Level): the clues of every try are shown sorted – first O, then ?, then X – so they no longer tell which digit they belong to, as in the classic board game. Points ×' + p.expert + '. It starts with the next game; the number of the day always counts normally. Fewer tries than in the table add 5 % per try. The best possible game – 8 digits, Expert, 2 tries, fast, no hints – is worth about ' + p.best + ' points. On the world top 20 everybody is on one list; ⭐ marks a score played at the Expert level.'; },
      'help.modesWord': function (p) { return 'Harder settings multiply your points (⚙): only real words accepted ×' + p.real + ', Expert level ×' + p.expert + ', both together ×' + p.both + '. “Only real words” counts when it is on for the whole game; the word of the day always counts normally. Fewer tries than in the table add 5 % per try. The best possible game – 8 letters, Expert with only real words, 2 tries, fast, no hints – is worth about ' + p.best + ' points. On the world top 20 everybody is on one list; ⭐ and 📖 show how a score was played.'; },
