      'help.dailyReward': function (p) { return 'Reward: every solved puzzle of the day gives ' + p.n + ' hint ' + pl(p.n, 'credit', 'credits') + ' – also when you play as Anonymous – and days in a row give a bonus: ' + p.list + ', then +' + p.rep + ' every ' + p.every + ' days. Each game pays once a day.'; },
      'credits.dailyRewards': function (p) { return 'Puzzles of the day: +' + p.n + ' ' + pl(p.n, 'credit', 'credits') + ' for each one solved, also for Anonymous; days in a row: ' + p.list + '.'; },
      'share.dailyHead': function (p) { return '🧩 MBG Puzzles – ' + p.title + ' #' + p.n + (p.extra ? ' (' + p.extra + ')' : ''); },
      'share.dailyWon': function (p) { return '✅ I solved it in ' + p.tries + ' ' + pl(p.tries, 'try', 'tries') + ' · ⏱ ' + p.time + (p.hints ? ' · 💡 ' + p.hints + ' ' + pl(p.hints, 'hint', 'hints') : ''); },
      'share.dailyLost': function (p) { return '❌ Not solved today (' + p.tries + ' ' + pl(p.tries, 'try', 'tries') + ')'; },
      'share.dailyStreak': function (p) { return '🔥 ' + p.n + ' days in a row'; },
