      'account.remind': 'E-mail nga loja (kujtesa dhe urime)',
      'account.remindText': 'Kur e gjen numrin ose fjalën e ditës, të dërgojmë një urim të shkurtër me vendin tënd (më së shumti një e-mail në ditë). Nëse nuk luan rreth 3 ditë, të dërgojmë një kujtesë miqësore. Mund ta fikësh kur të duash; çdo e-mail ka një lidhje për t’i ndaluar.',
      'account.remindOpt': 'Mos më dërgoni e-mail nga loja',
      'help.creditRewards': function (p) { return 'Kredite për sugjerime për pikë të larta (lojtarë të hyrë me emër): ' + p.list + '.'; },
      'help.modesCode': function (p) { return 'Niveli ekspert ⭐ (⚙ › Niveli): shenjat e çdo prove shfaqen të renditura – fillimisht O, pastaj ?, pastaj X – kështu që nuk tregojnë më cilës shifër i përkasin, si në lojën klasike të tavolinës. Pikët ×' + p.expert + '. Fillon nga loja e ardhshme; numri i ditës numërohet gjithmonë normalisht. Më pak prova se në tabelë shtojnë 5 % për çdo provë. Loja më e mirë e mundshme – 8 shifra, ekspert, 2 prova, shpejt, pa sugjerime – vlen rreth ' + p.best + ' pikë. Te 20 më të mirët në botë të gjithë janë në një listë; ⭐ shënon një rezultat të luajtur në nivelin ekspert.'; },
      'help.modesWord': function (p) { return 'Cilësimet më të vështira i shumëzojnë pikët (⚙): vetëm fjalë të vërteta ×' + p.real + ', niveli ekspert ×' + p.expert + ', të dyja bashkë ×' + p.both + '. “Vetëm fjalë të vërteta” vlen kur është e ndezur gjatë gjithë lojës; fjala e ditës numërohet gjithmonë normalisht. Më pak prova se në tabelë shtojnë 5 % për çdo provë. Loja më e mirë e mundshme – 8 shkronja, ekspert me vetëm fjalë të vërteta, 2 prova, shpejt, pa sugjerime – vlen rreth ' + p.best + ' pikë. Te 20 më të mirët në botë të gjithë janë në një listë; ⭐ dhe 📖 tregojnë si është luajtur një rezultat.'; },
      'help.modesTitle': 'Shpërblimi për vështirësinë ⭐',
      'world.legendCode': '⭐ Niveli ekspert (shenjat nuk tregojnë vendin e tyre). Lojërat më të vështira japin më shumë pikë.',
      'world.legendWord': '⭐ Niveli ekspert · 📖 pranohen vetëm fjalë të vërteta. Lojërat më të vështira japin më shumë pikë.',
