      'help.modesWord': function (p) { return 'Teže postavke množe tvoje bodove (⚙): samo prave riječi ×' + p.real + ', nivo ekspert ×' + p.expert + ', oboje zajedno ×' + p.both + '. „Samo prave riječi” se računa kad je uključeno tokom cijele igre; riječ dana se uvijek računa normalno. Manje pokušaja nego u tabeli donosi 5 % više po pokušaju. Najbolja moguća igra – 8 slova, ekspert sa samo pravim riječima, 2 pokušaja, brzo, bez nagovještaja – vrijedi oko ' + p.best + ' bodova. Na listi Top 20 svijeta svi su na jednoj listi; ⭐ i 📖 pokazuju kako je rezultat odigran.'; },
