      'daily.reward': function (p) { return '+' + p.n + ' ' + plBs(p.n, 'kredit', 'kredita', 'kredita') + ' za nagovještaje za današnju zagonetku'; },
      'daily.bonus': function (p) { return p.days + ' ' + plBs(p.days, 'dan', 'dana', 'dana') + ' zaredom: +' + p.n + ' bonus ' + plBs(p.n, 'kredit', 'kredita', 'kredita') + '!'; },
      'daily.nextBonus': function (p) { return 'Sljedeći bonus: ' + p.days + ' dana zaredom (+' + p.n + '), još ' + p.left + ' ' + plBs(p.left, 'dan', 'dana', 'dana'); },
      'daily.rewardTomorrow': function (p) { return 'Riješi sutrašnju zagonetku za +' + p.n + ' ' + plBs(p.n, 'kredit', 'kredita', 'kredita') + ' za nagovještaje.'; },
      'daily.rewardLine': function (p) { return 'Svaka riješena zagonetka: +' + p.n + ' ' + plBs(p.n, 'kredit', 'kredita', 'kredita') + ' za nagovještaje 💡 · bonus za dane zaredom: ' + p.list; },
      'daily.bonusItem': function (p) { return p.days + ' dana +' + p.n; },
      'dtop.title': 'Najbolje zagonetke dana',
      'dtop.open': '🏆 Najbolje zagonetke dana',
      'dtop.hidden': 'vidi se kad dan prođe',
      'dtop.note': 'Zagonetka dana je ista za sve. Njen broj ili riječ se ovdje prikazuje kad taj dan prođe svuda na svijetu.',
      'dtop.empty': 'Ovdje još niko nije riješio zagonetku dana. Riješi današnju i budi prvi!',
      'dtop.count': function (p) { return p.n + ' ' + plBs(p.n, 'riješena zagonetka dana', 'riješene zagonetke dana', 'riješenih zagonetki dana'); },
      'help.dailyReward': function (p) { return 'Nagrada: svaka riješena zagonetka dana donosi ' + p.n + ' ' + plBs(p.n, 'kredit', 'kredita', 'kredita') + ' za nagovještaje – i kad igraš kao Anonimno – a dani zaredom donose bonus: ' + p.list + ', zatim +' + p.rep + ' svakih ' + p.every + ' dana. Svaka igra nagrađuje jednom dnevno.'; },
      'credits.dailyRewards': function (p) { return 'Zagonetke dana: +' + p.n + ' ' + plBs(p.n, 'kredit', 'kredita', 'kredita') + ' za svaku riješenu, i za Anonimno; dani zaredom: ' + p.list + '.'; },
      'share.dailyHead': function (p) { return '🧩 MBG Puzzles – ' + p.title + ' #' + p.n + (p.extra ? ' (' + p.extra + ')' : ''); },
      'share.dailyWon': function (p) { return '✅ Riješeno u ' + p.tries + ' ' + plBs(p.tries, 'pokušaju', 'pokušaja', 'pokušaja') + ' · ⏱ ' + p.time + (p.hints ? ' · 💡 ' + p.hints + ' ' + plBs(p.hints, 'nagovještaj', 'nagovještaja', 'nagovještaja') : ''); },
      'share.dailyLost': function (p) { return '❌ Danas nije riješeno (' + p.tries + ' ' + plBs(p.tries, 'pokušaj', 'pokušaja', 'pokušaja') + ')'; },
      'share.dailyStreak': function (p) { return '🔥 ' + p.n + ' ' + plBs(p.n, 'dan', 'dana', 'dana') + ' zaredom'; },
      'share.legendCode': '🟩 tačna cifra na pravom mjestu · 🟨 u broju, ali na drugom mjestu · ⬛ nije u broju',
      'share.legendWord': '🟩 tačno slovo na pravom mjestu · 🟨 u riječi, ali na drugom mjestu · ⬛ nije u riječi',
      'share.hiddenCode': 'Svaki red je jedan moj pokušaj – cifre ostaju skrivene da ti ne pokvarim igru.',
      'share.hiddenWord': 'Svaki red je jedan moj pokušaj – slova ostaju skrivena da ti ne pokvarim igru.',
      'share.challenge': 'Možeš li bolje? Današnja zagonetka je ista za sve i besplatna:',
      'share.copiedPaste': 'Kopirano – sada ga zalijepi u bilo koji chat ili poruku.',
      'share.title': 'Podijeli putem',
      'share.sms': 'SMS',
      'share.more': 'Više aplikacija',
      'settings.keys': 'Zvukovi tipki',
      'settings.keysHint': 'Drvo: svaka cifra i slovo kucne kao drveni blok, svaka tipka svojim tonom, a sat kuca tik-tak kao drvo. Različiti / Isti: pištanje kao tipke starog telefona s tipkama (slova na svojoj tipki: ABC = 2), svaka tipka svoj ton ili jedan ton za sve.',
      'promo.alt': 'MBG Games: igra s brojevima i igra s riječima. Misli, pogodi, riješi, zabavi se!',
      'menu.title': 'Meni',
      'menu.open': 'Otvori meni',
