      'lock.warnFree': ' Das war dein Gratisspiel für heute.',

      'pay.title': 'Spiel ohne Grenzen',
      'pay.reasonLocked': function (p) { return 'Du hast das heutige Gratisspiel in „' + p.game + '“ gespielt. Dein nächstes Gratisspiel beginnt in ' + p.time + '.'; },
      'pay.reasonTrial': function (p) { return 'Deine Gratiswoche: ' + (p.daysLeft <= 1 ? 'letzter Tag.' : 'noch ' + p.daysLeft + ' Tage.') + ' Danach bekommst du alle 24 Stunden ein Gratisspiel pro Spiel.'; },
      'pay.reasonFree': 'Mit dem Gratis-Tarif bekommst du alle 24 Stunden ein Gratisspiel pro Spiel.',
      'pay.reasonSub': 'Dein Abo ist aktiv: Beide Spiele sind ohne Grenzen.',
      'pay.pick': 'Wähle einen Tarif',
