      'plan.yearly': 'Jährlich',
      'per.weekly': 'pro Woche',
      'per.monthly': 'pro Monat',
      'per.yearly': 'pro Jahr',
      'pay.terms': 'Jeder Tarif verlängert sich automatisch zum angezeigten Preis, jede Woche, jeden Monat oder jedes Jahr, bis du kündigst. Du bezahlst mit deinem Google-Play-Konto. Kündigen kannst du jederzeit in Google Play › Zahlungen und Abos › Abos; du spielst dann bis zum Ende des bezahlten Zeitraums ohne Grenzen weiter.',
      'pay.notNowLocked': function (p) { return 'Nicht jetzt · wieder gratis in ' + p.time; },
      'pay.notNowTrial': 'Nicht jetzt · gratis weiterspielen',
      'pay.notNow': 'Nicht jetzt',
      'pay.restore': 'Kauf wiederherstellen',
      'pay.loading': 'Preise werden von Google Play geladen …',
      'pay.unavailable': 'Die Tarife konnten nicht geladen werden. Prüf deine Internetverbindung und versuch es noch einmal.',
      'pay.retry': 'Nochmal versuchen',
      'pay.preview': 'Vorschau: In der Android-App kommen die Tarife und Preise von Google Play.',
      'pay.webOnly': 'Abos gibt es in der App MBG Puzzles auf Google Play.',
      'pay.busy': 'Google Play wird geöffnet …',
      'pay.thanks': 'Danke! Beide Spiele sind jetzt ohne Grenzen.',
      'pay.pending': 'Deine Zahlung wartet auf Bestätigung. Sobald Google Play sie bestätigt, spielst du ohne Grenzen.',
      'pay.error': 'Der Kauf hat nicht geklappt. Bitte versuch es noch einmal.',
      'pay.restored': 'Dein Abo ist aktiv.',
      'pay.noneFound': 'Für das Google-Konto auf diesem Handy wurde kein aktives Abo gefunden.',

      'help.hintsPaid': 'Tipp-Guthaben: Jeden Tag bekommt jeder Spielername 5 Gratis-Credits (bis zu 15 pro Woche). Mehr gibt es in Paketen mit 50, 100 oder 200 Credits (1 Credit = 0,10 €) oder für hohe Punktzahlen. Die ganze Lösung zu sehen kostet 9 Credits; ein neues Spiel ist immer gratis. Ein Abo gibt unbegrenzt Spiele, keine Credits.',
      'help.planTitle': 'Gratiswoche und Abo',
      'help.plan': 'In den ersten 7 Tagen kannst du beide Spiele so viel spielen, wie du willst. Danach bekommst du alle 24 Stunden ein Gratisspiel in Knack den Code und ein Gratisspiel in Errate das Wort. Ein Spiel zählt ab deinem ersten Versuch. Mit einem Abo (wöchentlich, monatlich oder jährlich) sind beide Spiele ohne Grenzen. Du bezahlst über Google Play; das Abo verlängert sich automatisch, bis du es in Google Play unter Zahlungen und Abos › Abos kündigst.',

      'world.title': 'Welt-Top-20',
      'world.cardText': 'Die besten Spieler aus allen Ländern. Schaffst du es auf die Liste?',
      'world.week': '2 Wochen',
      'world.older': "Frühere Ergebnisse",
      'world.all': 'Aller Zeiten',
