      'world.letters': function (p) { return p.n + ' Buchstaben'; },
      'world.tries': function (p) { return p.n + ' ' + pl(p.n, 'Versuch', 'Versuche'); },
      'reveal.buyTitle': 'Lösung ansehen',
      'reveal.buyText': function (p) { return 'Zeigt ' + p.what + ' und beendet dieses Spiel mit 0 Punkten. Das kostet ' + p.n + ' Credits (du hast ' + p.have + '). Du kannst auch gratis ein neues Spiel beginnen, ohne die Lösung zu sehen.'; },
      'reveal.use': function (p) { return p.n + ' Credits einsetzen'; },
      'reveal.buy': 'Credits kaufen',
      'hint.notNow': 'Nicht jetzt',
      'credits.title': '💡 Tipp-Guthaben',
      'credits.anon': 'Anonym',
      'credits.total': function (p) { return p.n + ' ' + pl(p.n, 'Credit', 'Credits'); },
      'credits.free': function (p) { return 'Heute gratis: ' + p.n + ' (bis zu ' + p.day + ' pro Tag, ' + p.week + ' pro Woche).'; },
      'credits.freeNext': function (p) { return 'Neue Gratis-Credits in ' + p.time + '.'; },
      'credits.own': function (p) { return 'Gekauft und verdient: ' + p.n + '.'; },
      'credits.ownFree': function (p) { return 'Mit hohen Punktzahlen verdient: ' + p.n + '.'; },
      'credits.howTitle': 'So funktioniert es',
      'credits.how': function (p) { return 'Ein Tipp deckt einen Buchstaben oder eine Ziffer auf und kostet 1 Credit. Zuerst werden die Gratis-Credits verwendet. Mit gekauften oder verdienten Credits kosten die Tipps eines Spiels ' + p.steps + ' Credits; jedes neue Spiel beginnt wieder bei 1.'; },
      'credits.howFree': function (p) { return 'Ein Tipp deckt einen Buchstaben oder eine Ziffer auf und kostet 1 Credit. Zuerst werden die Gratis-Credits verwendet. Mit verdienten Credits kosten die Tipps eines Spiels ' + p.steps + ' Credits; jedes neue Spiel beginnt wieder bei 1.'; },
      'credits.rewardsTitle': 'Credits für hohe Punktzahlen',
      'credits.rewards': function (p) { return 'Punkte → Credits: ' + p.list + '. Nur für Spieler, die mit einem Namen angemeldet sind.'; },
      'credits.buyTitle': function (p) { return 'Credits kaufen (1 Credit = ' + p.value + ')'; },
      'credits.pack': function (p) { return p.n + ' Credits – ' + p.price; },
      'credits.phoneNote': function (p) { return 'Die Credits werden auf diesem Handy gespeichert, für ' + p.name + '.'; },
      'credits.need': function (p) { return 'Dafür brauchst du ' + p.n + ' ' + pl(p.n, 'Credit', 'Credits') + ' – du hast ' + p.have + '.'; },
      'credits.none': function (p) { return 'Kein Tipp-Guthaben mehr. Neue Gratis-Credits in ' + p.time + ' – auch hohe Punktzahlen bringen Credits.'; },
      'credits.bought': function (p) { return '+' + p.n + ' Credits. Danke!'; },
      'credits.spent': function (p) { return '−' + p.n + ' ' + pl(p.n, 'Credit', 'Credits') + ' · noch ' + p.left; },
      'credits.hintCost': function (p) { return 'Dieser Tipp kostet ' + p.n + ' Credits – du hast ' + p.have + '.'; },
      'credits.hintCostNote': function (p) { return 'In einem Spiel kosten Tipps mit deinen eigenen Credits ' + p.steps + '. Das nächste Spiel beginnt wieder bei 1.'; },
      'credits.use': function (p) { return p.n + ' Credits einsetzen'; },
      'credits.reward': function (p) { return '🎁 +' + p.n + ' Tipp-' + pl(p.n, 'Credit', 'Credits') + ' für ' + p.score + ' Punkte! Du hast jetzt ' + p.total + '.'; },
      'credits.rewardLogin': function (p) { return 'Melde dich mit einem Spielernamen an, dann bekommst du für solche Punktzahlen ' + p.n + ' Tipp-' + pl(p.n, 'Credit', 'Credits') + '.'; },
      'credits.web': 'Credits kaufst du in der Android-App, über Google Play.',
      'credits.pending': 'Die Zahlung wartet noch. Die Credits gehören dir, sobald sie bezahlt ist.',
      'credits.error': 'Der Kauf hat nicht geklappt. Bitte versuch es noch einmal.',
