      'help.modesCode': function (p) { return 'Nivel experto ⭐ (⚙ › Nivel): las pistas de cada intento se muestran ordenadas – primero O, luego ?, luego X – y ya no dicen a qué cifra corresponden, como en el clásico juego de mesa. Puntos ×' + p.expert + '. Empieza con la próxima partida; el número del día siempre cuenta normal. Menos intentos que en la tabla suman un 5 % por intento. La mejor partida posible – 8 cifras, experto, 2 intentos, rápido, sin pistas – vale unos ' + p.best + ' puntos. En el top 20 mundial todos están en una sola lista; ⭐ marca una puntuación del nivel experto.'; },
      'help.modesWord': function (p) { return 'Los ajustes más difíciles multiplican tus puntos (⚙): solo palabras reales ×' + p.real + ', nivel experto ×' + p.expert + ', ambos a la vez ×' + p.both + '. «Solo palabras reales» cuenta si está activado durante toda la partida; la palabra del día siempre cuenta normal. Menos intentos que en la tabla suman un 5 % por intento. La mejor partida posible – 8 letras, experto con solo palabras reales, 2 intentos, rápido, sin pistas – vale unos ' + p.best + ' puntos. En el top 20 mundial todos están en una sola lista; ⭐ y 📖 muestran cómo se jugó cada puntuación.'; },
