      'account.remindOnDone': 'Les e-mails du jeu sont activés.',
      'account.remind': 'E-mails du jeu (rappels et félicitations)',
      'account.remindText': 'Quand tu trouves le nombre ou le mot du jour, nous t’envoyons de brèves félicitations avec ta place (au plus un e-mail par jour). Si tu ne joues pas pendant environ 3 jours, nous t’envoyons un rappel amical. Tu peux le désactiver à tout moment ; chaque e-mail contient un lien pour ne plus en recevoir.',
      'account.remindOpt': 'Ne pas m’envoyer d’e-mails du jeu',
      'help.creditRewards': function (p) { return 'Crédits d’indices pour les bons scores (joueurs connectés avec un nom) : ' + p.list + '.'; },
      'help.modesCode': function (p) { return 'Niveau expert ⭐ (⚙ › Niveau) : les indices de chaque essai sont affichés triés – d’abord O, puis ?, puis X – et ne disent plus à quel chiffre ils correspondent, comme dans le jeu de société classique. Points ×' + p.expert + '. Cela commence à la prochaine partie ; le nombre du jour compte toujours normalement. Moins d’essais que dans le tableau ajoutent 5 % par essai. La meilleure partie possible – 8 chiffres, expert, 2 essais, rapide, sans indice – vaut environ ' + p.best + ' points. Dans le top 20 mondial, tout le monde est sur une seule liste ; ⭐ marque un score joué au niveau expert.'; },
      'help.modesWord': function (p) { return 'Les réglages plus difficiles multiplient tes points (⚙) : vrais mots seulement ×' + p.real + ', niveau expert ×' + p.expert + ', les deux ensemble ×' + p.both + '. « Vrais mots seulement » compte s’il reste activé pendant toute la partie ; le mot du jour compte toujours normalement. Moins d’essais que dans le tableau ajoutent 5 % par essai. La meilleure partie possible – 8 lettres, expert avec vrais mots seulement, 2 essais, rapide, sans indice – vaut environ ' + p.best + ' points. Dans le top 20 mondial, tout le monde est sur une seule liste ; ⭐ et 📖 montrent comment un score a été joué.'; },
