      'help.creditRewards': function (p) { return 'Yüksek puanlar için ipucu kredisi (bir adla giriş yapmış oyuncular): ' + p.list + '.'; },
      'help.modesCode': function (p) { return 'Uzman seviyesi ⭐ (⚙ › Seviye): her denemenin ipuçları sıralı gösterilir – önce O, sonra ?, sonra X – böylece klasik masa oyunundaki gibi hangi rakama ait oldukları artık anlaşılmaz. Puan ×' + p.expert + '. Bir sonraki oyundan başlar; günün sayısı her zaman normal sayılır. Tablodakinden az deneme, her deneme için %5 ekler. Mümkün olan en iyi oyun – 8 rakam, uzman, 2 deneme, hızlı, ipucusuz – yaklaşık ' + p.best + ' puan eder. Dünya ilk 20 listesinde herkes tek bir listede; ⭐ uzman seviyesinde oynanmış bir puanı gösterir.'; },
      'help.modesWord': function (p) { return 'Daha zor ayarlar puanını katlar (⚙): yalnızca gerçek kelimeler ×' + p.real + ', uzman seviyesi ×' + p.expert + ', ikisi birlikte ×' + p.both + '. “Yalnızca gerçek kelimeler” oyun boyunca açık kalırsa sayılır; günün kelimesi her zaman normal sayılır. Tablodakinden az deneme, her deneme için %5 ekler. Mümkün olan en iyi oyun – 8 harf, yalnızca gerçek kelimelerle uzman, 2 deneme, hızlı, ipucusuz – yaklaşık ' + p.best + ' puan eder. Dünya ilk 20 listesinde herkes tek bir listede; ⭐ ve 📖 bir puanın nasıl oynandığını gösterir.'; },
