      'help.modesCode': function (p) { return 'Poziom ekspert ⭐ (⚙ › Poziom): wskazówki każdej próby są pokazane posortowane – najpierw O, potem ?, potem X – więc nie mówią już, do której cyfry należą, jak w klasycznej grze planszowej. Punkty ×' + p.expert + '. Działa od następnej gry; liczba dnia zawsze liczy się normalnie. Mniej prób niż w tabeli dodaje 5 % za każdą próbę. Najlepsza możliwa gra – 8 cyfr, ekspert, 2 próby, szybko, bez podpowiedzi – jest warta około ' + p.best + ' punktów. W światowym top 20 wszyscy są na jednej liście; ⭐ oznacza wynik z poziomu ekspert.'; },
      'help.modesWord': function (p) { return 'Trudniejsze ustawienia mnożą twoje punkty (⚙): tylko prawdziwe słowa ×' + p.real + ', poziom ekspert ×' + p.expert + ', oba naraz ×' + p.both + '. „Tylko prawdziwe słowa” liczy się, gdy jest włączone przez całą grę; słowo dnia zawsze liczy się normalnie. Mniej prób niż w tabeli dodaje 5 % za każdą próbę. Najlepsza możliwa gra – 8 liter, ekspert z tylko prawdziwymi słowami, 2 próby, szybko, bez podpowiedzi – jest warta około ' + p.best + ' punktów. W światowym top 20 wszyscy są na jednej liście; ⭐ i 📖 pokazują, jak zdobyto wynik.'; },
