      'help.modesWord': function (p) { return 'Configurações mais difíceis multiplicam seus pontos (⚙): só palavras de verdade ×' + p.real + ', nível especialista ×' + p.expert + ', os dois juntos ×' + p.both + '. “Só palavras de verdade” conta quando fica ligado durante toda a partida; a palavra do dia sempre conta normal. Menos tentativas do que na tabela somam 5 % por tentativa. A melhor partida possível – 8 letras, especialista com só palavras de verdade, 2 tentativas, rápida, sem dicas – vale cerca de ' + p.best + ' pontos. No top 20 mundial todos ficam numa só lista; ⭐ e 📖 mostram como uma pontuação foi jogada.'; },
