      'help.modesCode': function (p) { return '전문가 레벨 ⭐ (⚙ › 레벨): 시도마다 단서가 O, ?, X 순서로 정렬되어 보여서, 고전 보드게임처럼 어느 숫자의 단서인지 알 수 없어요. 점수 ×' + p.expert + '. 다음 게임부터 적용되고, 오늘의 숫자는 늘 일반 점수로 계산돼요. 표보다 시도가 적으면 한 번 줄 때마다 5%씩 더 받아요. 가장 좋은 게임 – 8자리, 전문가, 2번 만에, 빠르게, 힌트 없이 – 은 약 ' + p.best + '점이에요. 세계 TOP 20은 모두 한 목록이고, ⭐는 전문가 레벨로 낸 점수를 뜻해요.'; },
      'help.modesWord': function (p) { return '어려운 설정을 고를수록 점수가 커져요 (⚙): 실제 단어만 인정 ×' + p.real + ', 전문가 레벨 ×' + p.expert + ', 둘 다 ×' + p.both + '. ‘실제 단어만’은 게임 내내 켜져 있을 때만 적용되고, 오늘의 단어는 늘 일반 점수로 계산돼요. 표보다 시도가 적으면 한 번 줄 때마다 5%씩 더 받아요. 가장 좋은 게임 – 8칸, 전문가 + 실제 단어만, 2번 만에, 빠르게, 힌트 없이 – 은 약 ' + p.best + '점이에요. 세계 TOP 20은 모두 한 목록이고, ⭐와 📖는 점수를 낸 방식을 보여 줘요.'; },
